    CONSTRAINT inventory_settings_lot_outflow_strategy_check CHECK (((lot_outflow_strategy)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('FIFO'::character varying)::text, ('FEFO'::character varying)::text])))
